  evier: { nom: _tk("Évier"), cat: _tk("Cuisine"), taille: [100, 60], d: (w, h) => R_(-w / 2, -h / 2, w, h, 3) + R_(-w / 2 + 8, -h / 2 + 14, w / 2 - 12, h - 22, 8, "vide") + R_(4, -h / 2 + 14, w / 2 - 12, h - 22, 8, "vide") + C_(0, -h / 2 + 7, 3) },
