const etiquettesPieces = (c) => { const o = c?.etiquettes_pieces && typeof c.etiquettes_pieces === "object" ? c.etiquettes_pieces : {}; return { nom: o.nom !== false, temperature: o.temperature !== false, humidite: o.humidite !== false }; };

