        const o = d.ouvertures[m.i], [a, b, c, e] = o.seg, [nx, ny] = o.dehors || [0, 0], mi = [(a + c) / 2, (b + e) / 2];
        const p = dans([mi[0] - nx * 40, mi[1] - ny * 40]) || dans([mi[0] + 40, mi[1]]) || dans([mi[0] - 40, mi[1]]) || dans([mi[0], mi[1] + 40]) || dans([mi[0], mi[1] - 40]);
