    const interrupteur = ev.composedPath().some((n) => n instanceof HTMLInputElement && (n.type === "checkbox" || n.type === "radio" || n.type === "range"));
    if (this._menuOuvert) return; // menu déroulant ouvert : il gère ses touches (flèches, Échap)
